function meta = export_sic_preamble(outDir, cxxRunDir)
%EXPORT_SIC_PREAMBLE  MATLAB export of one representative S0 case.
%
%   META = EXPORT_SIC_PREAMBLE() writes into
%   testdata/sic_preamble/matlab/out/ for the default C++ run directory
%   gr-uwb/build-sic/sic-results/main_est:
%
%     comm_sync_code10_998p4.cf32     code-10 SYNC template (independent)
%     comm_preamble_code10_998p4.cf32 code-10 full 64-SYNC preamble (independent)
%     sensing_sync_code9_998p4.cf32   code-9 sensing SYNC template (independent)
%     s_998p4.cf32                    clean sensing window  (LOADED from C++)
%     i_998p4.cf32                    interferer            (MATLAB regenerated)
%     y_998p4.cf32                    s + i + w             (MATLAB AWGN)
%     detected_start.json             independent detector vs C++ sic_state
%     sic_cir_raw_998p4.cf32          per-tap SIC matched-filter CIR (raw)
%     sic_cir_norm_998p4.cf32         per-tap SIC matched-filter CIR (L2 norm)
%     radar_cir_raw_998p4.cf32        per-tap sensing radar CIR (estimateCir port)
%     radar_cir_norm_998p4.cf32       per-tap sensing radar CIR (L2 norm)
%     export_meta.json
%
%   META = EXPORT_SIC_PREAMBLE(OUTDIR, CXXRUNDIR) overrides both paths.
%
%   Independence (per §3.3 / §9 of the S0 instruction):
%     * comm and sensing templates are generated by the MATLAB
%       lrwpanWaveformGenerator path in export_comm_template.m, never copied
%       from the C++ output.
%     * `i` is REGENERATED in MATLAB from the comm template, the truth-side
%       channel (delay/gain/CFO/offset) recorded by the generator, and the
%       §3.1 ISR scaling rule.  Only the clean `s` and the generator truth are
%       shared inputs.
%     * the detection start is produced by an independent normalised-correlation
%       detector, and the per-tap CIR by an independent matched filter /
%       estimateCir port, both run on the C++ received window `y` / `s`.
%     * `w` (AWGN) is NOT comparable: MATLAB and NumPy use different RNGs, so
%       `y` is exported only as a s+i+w reference record.  The verifier compares
%       the deterministic part `s + i` and reports the C++ AWGN RMS as a floor.
%
%   The C++ artifact layout consumed here is the S0 run layout under
%   gr-uwb/build-sic/sic-results/<run>/:
%     templates/comm_sync_code10_998p4.cf32
%     templates/comm_preamble_code10_998p4.cf32
%     templates/sync_template_code9_998p4.cf32
%     fixtures/window_0000.npz   (s, i, w, y, seed, isr_db, overlap_lo, overlap_hi)
%     fixtures/truth.jsonl       (channel truth; generator side only)
%
%   NOTE (未实跑): no MATLAB/Octave on the development host.  See README.md and
%   not_run.log.  This script was reviewed for syntax but has NOT been run.

    if nargin < 1 || isempty(outDir)
        outDir = fullfile(fileparts(mfilename('fullpath')), 'out');
    end
    here = fileparts(mfilename('fullpath'));
    repo = fileparts(fileparts(fileparts(here)));   % .../testdata/sic_preamble/matlab
    if nargin < 2 || isempty(cxxRunDir)
        cxxRunDir = fullfile(repo, 'gr-uwb', 'build-sic', 'sic-results', 'main_est');
    end
    if ~exist(cxxRunDir, 'dir')
        error('export_sic_preamble:NoRunDir', ...
            ['C++ run directory not found: %s\n' ...
             'Generate it first (uwb_sim_preamble_sic.py --preset main ...) ' ...
             'or pass CXXRUNDIR explicitly; this exporter does not fabricate ' ...
             'the clean sensing window.'], cxxRunDir);
    end
    if ~exist(outDir, 'dir')
        mkdir(outDir);
    end

    % --- ensure the independent templates exist --------------------------
    if exist(fullfile(outDir, 'comm_preamble_code10_998p4.cf32'), 'file') ~= 2
        export_comm_template(outDir);
    end
    commSync = local_read_cf32(fullfile(outDir, 'comm_sync_code10_998p4.cf32'));
    commPre = local_read_cf32(fullfile(outDir, 'comm_preamble_code10_998p4.cf32'));
    sensingSync = local_read_cf32(fullfile(outDir, 'sensing_sync_code9_998p4.cf32'));

    % --- C++ case parameters + fixture -----------------------------------
    win = local_read_first_jsonl(fullfile(cxxRunDir, 'windows.jsonl'));
    truth = local_read_first_jsonl(fullfile(cxxRunDir, 'fixtures', 'truth.jsonl'));
    npzPath = local_first_existing({ ...
        fullfile(cxxRunDir, 'fixtures', 'window_0000.npz'), ...
        fullfile(cxxRunDir, 'fixtures', 'window_0.npz')});
    if isempty(npzPath)
        error('export_sic_preamble:NoFixture', ...
            'no fixtures/window_0000.npz under %s', cxxRunDir);
    end
    s = local_read_npz_array(npzPath, 's');
    iCxx = local_read_npz_array(npzPath, 'i');
    y = local_read_npz_array(npzPath, 'y');
    w = local_read_npz_array(npzPath, 'w');
    s = s(:); iCxx = iCxx(:); y = y(:); w = w(:);
    n = numel(s);
    % C++ fixture identity check: y == s + i + w (complex64 expression).
    yIdentity = max(abs(double(y) - (double(s) + double(iCxx) + double(w))));

    sampleRate = local_field(win, 'sample_rate', 998.4e6);
    sensingCode = local_field(win, 'sensing_code', 9);
    commCode = local_field(win, 'comm_code', 10);
    syncReps = local_field(win, 'sensing_sync_reps', 64);
    fitReps = local_field(win, 'fit_reps', 8);
    roi = local_field(win, 'roi', [1997, 67021]);
    sfdMode = char(local_field(win, 'sensing_sfd_mode', '4z2'));
    snrDb = local_field(win, 'snr_db', 30.0);
    cxxDetectedStart = NaN;
    if isfield(win, 'sic_state') && isfield(win.sic_state, 'detected_start')
        cxxDetectedStart = double(win.sic_state.detected_start);
    end

    geom = truth.sensing.geometry;
    pre = double(geom.pre_guard);
    commPaths = truth.comm.paths;
    commStart = double(truth.comm.start_sample_exact);
    commLen = double(truth.comm.length_samples);
    cfoHz = double(truth.comm.cfo_hz);
    isrDb = double(truth.comm.isr_db);
    fracModel = 'pchip';

    % --- independent regeneration of i -----------------------------------
    raw = zeros(n, 1);
    for k = 1:numel(commPaths)
        g = commPaths(k).gain;
        raw = local_apply_path(raw, commPre, pre, ...
            double(commPaths(k).delay_samples), complex(g(1), g(2)), fracModel);
    end
    offset = commStart - pre;
    if abs(offset) > 1e-12
        raw = local_shift_frac(raw, offset, fracModel);
    end
    if cfoHz ~= 0
        t = (0:n-1).' / sampleRate;
        raw = raw .* exp(1j * 2 * pi * cfoHz * t);
    end
    % §3.1 ISR scale over the overlap [lo,hi) against the clean sensing energy.
    sensingLo = pre;
    sensingHi = min(pre + syncReps * 1016, n);
    lo = max(floor(commStart), sensingLo);
    hi = min(ceil(commStart) + commLen, sensingHi);
    e_s = sum(abs(double(s(lo+1:hi))).^2);
    e_i = sum(abs(raw(lo+1:hi)).^2);
    if e_i > 0 && e_s > 0 && ~isnan(isrDb)
        scale = sqrt((e_s * 10.0^(isrDb / 10.0)) / e_i);
    else
        scale = 1.0;
    end
    iMatlab = single(raw * scale);

    % --- MATLAB AWGN (documented as NOT sample-comparable) ----------------
    % C++ uses the realised overlap [lo,hi) as the SNR reference interval.
    nRef = max(1, hi - lo);
    eRef = sum(abs(double(s(lo+1:hi))).^2);
    noiseStd = 0;
    if eRef > 0
        noiseStd = sqrt(eRef / (2.0 * nRef * 10.0^(snrDb / 10.0)));
    end
    rngState = rng;
    seed = double(local_field(win, 'seed', 1000000));
    rng(seed, 'twister');
    wMatlab = single((randn(n, 1) + 1j * randn(n, 1)) * noiseStd);
    rng(rngState);
    yMatlab = single(double(s) + double(iMatlab) + double(wMatlab));

    % --- independent detection on the C++ received window ----------------
    det = local_detect(double(y), commSync, double(roi), 14, 1016, fitReps);
    detected = struct();
    detected.matlab_detected_start = det.start0;
    detected.cxx_detected_start = cxxDetectedStart;
    detected.abs_diff = abs(det.start0 - cxxDetectedStart);
    detected.coarse_peak_ncc = det.coarse_ncc;
    detected.fine_peak_ncc = det.fine_ncc;
    detected.confirmed_reps = det.confirmed_reps;
    detected.roi = double(roi);
    detected.coarse_stride = 14;
    detected.samples_per_symbol = 1016;
    detected.method = 'normalised correlation (coarse stride 14 -> +-14 fine)';

    % --- independent per-tap CIRs ----------------------------------------
    sicCir = local_sic_cir(double(y), commSync, det.start0, 16, 100);
    cfgS9 = local_hrp_config(62.4, 6.81, syncReps, sensingCode, 2, 22, 2);
    ref = local_sampled_code(cfgS9, sensingCode);
    radarCir = local_estimate_cir(double(s), pre, ref, 16, 100, 10, syncReps);

    % --- write outputs ----------------------------------------------------
    files = struct();
    files.comm_sync_code10 = local_write_cf32( ...
        fullfile(outDir, 'comm_sync_code10_998p4.cf32'), commSync);
    files.comm_preamble_code10 = local_write_cf32( ...
        fullfile(outDir, 'comm_preamble_code10_998p4.cf32'), commPre);
    files.sensing_sync_code9 = local_write_cf32( ...
        fullfile(outDir, 'sensing_sync_code9_998p4.cf32'), sensingSync);
    files.s = local_write_cf32(fullfile(outDir, 's_998p4.cf32'), s);
    files.i = local_write_cf32(fullfile(outDir, 'i_998p4.cf32'), iMatlab);
    files.y = local_write_cf32(fullfile(outDir, 'y_998p4.cf32'), yMatlab);
    files.sic_cir_raw = local_write_cf32( ...
        fullfile(outDir, 'sic_cir_raw_998p4.cf32'), sicCir.raw);
    files.sic_cir_norm = local_write_cf32( ...
        fullfile(outDir, 'sic_cir_norm_998p4.cf32'), sicCir.norm);
    files.radar_cir_raw = local_write_cf32( ...
        fullfile(outDir, 'radar_cir_raw_998p4.cf32'), radarCir.raw);
    files.radar_cir_norm = local_write_cf32( ...
        fullfile(outDir, 'radar_cir_norm_998p4.cf32'), radarCir.norm);

    fid = fopen(fullfile(outDir, 'detected_start.json'), 'w');
    if fid < 0
        error('export_sic_preamble:WriteDet', 'cannot write detected_start.json');
    end
    fwrite(fid, jsonencode(detected));
    fclose(fid);

    meta = struct();
    meta.schema_version = 1;
    meta.generator = 'export_sic_preamble.m';
    meta.cxx_run_dir = cxxRunDir;
    meta.matlab_version = version;
    meta.sample_rate = sampleRate;
    meta.sensing_code = sensingCode;
    meta.comm_code = commCode;
    meta.sync_reps = syncReps;
    meta.samples_per_symbol = 1016;
    meta.sfd_mode = sfdMode;
    meta.pre_guard = pre;
    meta.window_samples = n;
    meta.overlap = struct('lo', lo, 'hi', hi, 'samples', hi - lo);
    meta.isr_db_target = isrDb;
    meta.isr_scale = scale;
    meta.comm_scale_truth = double(truth.comm.scale);
    meta.comm_scale_abs_diff = abs(scale - double(truth.comm.scale));
    meta.cxx_detected_start = cxxDetectedStart;
    meta.comm_start_exact = commStart;
    meta.comm_cfo_hz = cfoHz;
    meta.frac_model = fracModel;
    meta.snr_db = snrDb;
    meta.noise_std = noiseStd;
    meta.w_matlab_rng_seed = seed;
    meta.s_sha256 = local_sha256(s);
    meta.cxx_y_identity_max_abs = yIdentity;
    meta.i_method = 'matlab_independent_generator (template+paths+ISR rule)';
    meta.s_method = 'loaded_from_cxx_fixture (not regenerated)';
    meta.y_method = 's + i_matlab + w_matlab (MATLAB RNG; not sample-comparable)';
    meta.sic_cir = struct('pre', 16, 'post', 100, 'norm', 'l2', ...
        'taps', numel(sicCir.raw), 'sha256', local_sha256(sicCir.raw));
    meta.radar_cir = struct('pre', 16, 'post', 100, 'skip', 10, ...
        'reps_used', radarCir.valid, 'taps', numel(radarCir.raw), ...
        'sha256', local_sha256(radarCir.raw));
    meta.detected = detected;
    meta.files = files;
    meta.note = ['MATLAB cross-check exporter; NOT executed on the dev host ' ...
        '(no MATLAB/Octave) - see README.md and not_run.log.'];

    fid = fopen(fullfile(outDir, 'export_meta.json'), 'w');
    if fid < 0
        error('export_sic_preamble:WriteMeta', 'cannot write export_meta.json');
    end
    fwrite(fid, jsonencode(meta));
    fclose(fid);

    fprintf(['Exported S0 case to %s\n' ...
        '  window=%d samples  overlap=[%d,%d)  isr_scale=%.6g\n' ...
        '  detected_start: matlab=%d cxx=%g diff=%g (ncc=%.4f, reps=%d)\n' ...
        '  sic_cir=%d taps  radar_cir=%d taps (valid reps=%d)\n'], ...
        outDir, n, lo, hi, scale, det.start0, cxxDetectedStart, ...
        detected.abs_diff, det.fine_ncc, det.confirmed_reps, ...
        numel(sicCir.raw), numel(radarCir.raw), radarCir.valid);
end

% =========================================================================
% signal helpers (independent MATLAB implementation)
% =========================================================================

function rx = local_apply_path(rx, tx, base, delay, gain, ~)
    tx = tx(:);
    N = numel(rx);
    off = base + delay;
    if abs(delay - round(delay)) < 1e-9
        start0 = round(off);
        kLo = max(1, 1 - start0);
        kHi = min(numel(tx), N - start0);
        if kHi >= kLo
            r = (start0 + kLo):(start0 + kHi);
            rx(r) = rx(r) + gain * tx(kLo:kHi);
        end
        return;
    end
    baseStart = floor(off);
    frac = off - baseStart;
    y = zeros(N, 1);
    kLo = max(1, 1 - baseStart);
    kHi = min(numel(tx), N - baseStart);
    if kHi >= kLo
        y((baseStart + kLo):(baseStart + kHi)) = tx(kLo:kHi);
    end
    rx = rx + gain * local_shift_frac(y, frac, 'pchip');
end

function out = local_shift_frac(x, frac, ~)
    % Shift x RIGHT by `frac` samples with interp1 pchip, zero outside support.
    N = numel(x);
    xi = (0:N-1).';
    xq = xi - frac;
    idx = (xq >= 0) & (xq <= N-1);
    out = zeros(N, 1);
    if any(idx)
        out(idx) = interp1(xi, x, xq(idx), 'pchip', 0);
    end
end

function det = local_detect(y, sync, roi, stride, sps, fitReps)
    % Normalised-correlation detector, edge-anchored: the comm SYNC repeats,
    % so a plain argmax is ambiguous by k*sps.  Prefer the EARLIEST candidate
    % whose repetition run is confirmed and that has no comparable preamble
    % one symbol earlier (visible leading edge).
    y = y(:);
    N = numel(y);
    L = numel(sync);
    sn = sync(:) / norm(sync);
    nccf = @(s0) local_ncc(sn, y, s0, L);
    lo = max(1, roi(1) + 1);
    hi = min(N - L + 1, roi(2) - L + 1);
    if hi < lo
        det = struct('start0', -1, 'coarse_ncc', 0, 'fine_ncc', 0, ...
            'confirmed_reps', 0);
        return;
    end
    starts = lo:stride:hi;
    if starts(end) ~= hi
        starts(end+1) = hi; %#ok<AGROW>
    end
    coarseVals = zeros(numel(starts), 1);
    for k = 1:numel(starts)
        coarseVals(k) = nccf(starts(k));
    end
    globalMax = max(coarseVals);
    thresh = 0.5 * globalMax;
    cand = starts(coarseVals >= thresh);

    bestS = starts(1); bestVal = -1; confirmed = 0;
    for c = 1:numel(cand)
        cLo = max(lo, cand(c) - stride);
        cHi = min(hi, cand(c) + stride);
        pBest = cLo; pVal = -1;
        for s0 = cLo:cHi
            v = nccf(s0);
            if v > pVal
                pVal = v; pBest = s0;
            end
        end
        % visible leading edge: the previous symbol must not correlate
        prev = pBest - sps;
        edgeOk = true;
        if prev >= lo
            edgeOk = nccf(prev) < 0.5 * pVal;
        end
        reps = 0;
        for k = 1:fitReps-1
            s0 = pBest + k * sps;
            if s0 + L - 1 <= N
                if nccf(s0) >= 0.7 * pVal
                    reps = reps + 1;
                end
            end
        end
        if edgeOk && reps >= max(1, fitReps - 2)
            bestS = pBest; bestVal = pVal; confirmed = reps + 1;
            break;
        end
        if pVal > bestVal
            bestS = pBest; bestVal = pVal; confirmed = reps + 1;
        end
    end
    det = struct('start0', bestS - 1, 'coarse_ncc', globalMax, ...
        'fine_ncc', bestVal, 'confirmed_reps', confirmed);
end

function v = local_ncc(sn, y, s0, L)
    seg = y(s0:s0+L-1);
    v = abs(sn' * seg) / (norm(seg) + eps);
end

function cir = local_sic_cir(y, sync, start0, pre, post)
    y = y(:);
    N = numel(y);
    L = numel(sync);
    sn = sync(:) / norm(sync);
    taps = pre + post;
    raw = zeros(taps, 1);
    for t = 0:taps-1
        d = t - pre;
        s0 = start0 + d;          % 0-based first sample of the sync
        if s0 < 0 || s0 + L > N
            raw(t+1) = 0;
            continue;
        end
        raw(t+1) = sn' * y(s0+1:s0+L);
    end
    cir = struct('raw', raw, 'norm', raw / (norm(raw) + eps));
end

function cfg = local_hrp_config(meanPrf, dataRate, syncReps, codeIndex, ...
        samplesPerPulse, psduBytes, sfdNumber)
    attempts = {'BPRF', '802.15.4zBPRF', '802.15.4z', '802.15.4a'};
    lastErr = [];
    for k = 1:numel(attempts)
        try
            cfg = lrwpanHRPConfig('Mode', attempts{k}, 'MeanPRF', meanPrf, ...
                'DataRate', dataRate, 'PreambleDuration', syncReps, ...
                'CodeIndex', codeIndex, 'SamplesPerPulse', samplesPerPulse, ...
                'PSDULength', psduBytes, 'SFDNumber', sfdNumber);
            return;
        catch err
            lastErr = err;
        end
    end
    error('export_sic_preamble:NoHRPConfig', ...
        'lrwpanHRPConfig chain failed: %s', lastErr.message);
end

function ref = local_sampled_code(cfg, ~)
    % Port of export_uwb_radar_golden.m local_reference: sparse sampled code.
    code = lrwpan.internal.HRPCodes(cfg.CodeIndex);
    spread = zeros(numel(code) * cfg.PreambleSpreadingFactor, 1);
    spread(1:cfg.PreambleSpreadingFactor:end) = code(:);
    sampled = zeros(numel(spread) * cfg.SamplesPerPulse, 1);
    sampled(1:cfg.SamplesPerPulse:end) = spread;
    ref = struct('sampled_code', sampled, ...
        'code_energy', real(sampled' * sampled));
end

function cir = local_estimate_cir(rx, syncOrigin0, ref, pre, post, skip, nSync)
    % Port of estimateCir.m / export_uwb_radar_golden.m local_estimate_cir.
    code = ref.sampled_code(:);
    codeEnergy = ref.code_energy + eps;
    tapCount = pre + post;
    wlen = numel(code) + tapCount - 1;
    period = numel(code);
    acc = complex(zeros(wlen, 1));
    valid = 0;
    rx = rx(:);
    for k = skip:(nSync-1)
        rs = syncOrigin0 + k * period;   % 0-based SYNC start
        lo = rs - pre;                   % 0-based
        hi = lo + wlen - 1;
        if lo < 0 || hi > numel(rx) - 1
            continue;
        end
        acc = acc + rx(lo+1:hi+1);
        valid = valid + 1;
    end
    if valid < 1
        error('export_sic_preamble:NoCir', 'no complete SYNC windows');
    end
    avg = acc / valid;
    raw = conv(avg, flipud(conj(code)), 'valid') / codeEnergy;
    cir = struct('raw', raw, 'norm', raw / (norm(raw) + eps), 'valid', valid);
end

% =========================================================================
% I/O helpers
% =========================================================================

function x = local_read_cf32(path)
    fid = fopen(path, 'rb');
    if fid < 0
        error('export_sic_preamble:ReadCf32', 'cannot open %s', path);
    end
    raw = fread(fid, inf, 'float32=>single');
    fclose(fid);
    raw = raw(:);
    if mod(numel(raw), 2) ~= 0
        error('export_sic_preamble:Cf32Odd', '%s has odd element count', path);
    end
    x = complex(raw(1:2:end), raw(2:2:end));
end

function n = local_write_cf32(path, x)
    x = x(:);
    inter = zeros(2 * numel(x), 1, 'single');
    inter(1:2:end) = real(x);
    inter(2:2:end) = imag(x);
    fid = fopen(path, 'wb');
    if fid < 0
        error('export_sic_preamble:WriteCf32', 'cannot write %s', path);
    end
    fwrite(fid, inter, 'float32');
    fclose(fid);
    n = numel(x);
end

function v = local_read_npz_array(npzPath, key)
    tmp = tempname;
    mkdir(tmp);
    cleaner = onCleanup(@() local_rmdir(tmp)); %#ok<NASGU>
    unzip(npzPath, tmp);
    npy = fullfile(tmp, [key '.npy']);
    if exist(npy, 'file') ~= 2
        error('export_sic_preamble:NoNpzKey', ...
            '%s has no array "%s"', npzPath, key);
    end
    v = local_read_npy(npy);
end

function v = local_read_npy(path)
    % Minimal .npy v1/v2 reader for 1-D/0-D numeric arrays written by numpy.
    fid = fopen(path, 'rb');
    if fid < 0
        error('export_sic_preamble:ReadNpy', 'cannot open %s', path);
    end
    cleaner = onCleanup(@() fclose(fid)); %#ok<NASGU>
    magic = fread(fid, 6, 'uint8=>uint8').';
    if ~isequal(magic, [147 78 85 77 80 89])
        error('export_sic_preamble:BadNpy', 'not a .npy file: %s', path);
    end
    major = fread(fid, 1, 'uint8');
    fread(fid, 1, 'uint8');   % minor
    if major == 1
        hlen = fread(fid, 1, 'uint16=>double', 0, 'ieee-le');
    else
        hlen = fread(fid, 1, 'uint32=>double', 0, 'ieee-le');
    end
    hdr = char(fread(fid, hlen, 'uint8=>uint8').');
    descr = regexp(hdr, '''descr''\s*:\s*''([^'']+)''', 'tokens', 'once');
    shape = regexp(hdr, '''shape''\s*:\s*\(([^\)]*)\)', 'tokens', 'once');
    fortran = ~isempty(regexp(hdr, '''fortran_order''\s*:\s*True', 'once'));
    if isempty(descr) || isempty(shape)
        error('export_sic_preamble:BadNpyHeader', 'bad .npy header: %s', path);
    end
    descr = descr{1};
    dimsStr = strtrim(shape{1});
    if isempty(dimsStr)
        dims = 1;
    else
        dims = str2double(strsplit(strrep(dimsStr, ',', ' ')));
        dims = dims(~isnan(dims));
        if isempty(dims)
            dims = 1;
        end
    end
    nElem = prod(dims);
    switch descr
        case '<c8'
            raw = fread(fid, 2 * nElem, 'float32=>single', 0, 'ieee-le');
            v = complex(raw(1:2:end), raw(2:2:end));
        case '<f8'
            v = fread(fid, nElem, 'float64=>double', 0, 'ieee-le');
        case '<f4'
            v = fread(fid, nElem, 'float32=>single', 0, 'ieee-le');
        case '<i8'
            v = fread(fid, nElem, 'int64=>int64', 0, 'ieee-le');
        case '<i4'
            v = fread(fid, nElem, 'int32=>int32', 0, 'ieee-le');
        otherwise
            error('export_sic_preamble:NpyDtype', ...
                'unsupported .npy dtype %s in %s', descr, path);
    end
    if numel(dims) > 1 && ~fortran
        v = reshape(v, fliplr(dims)).';   % C order
    elseif numel(dims) > 1
        v = reshape(v, dims);             % Fortran order
    else
        v = v(:);
    end
end

function obj = local_read_first_jsonl(path)
    fid = fopen(path, 'r');
    if fid < 0
        error('export_sic_preamble:ReadJsonl', 'cannot open %s', path);
    end
    cleaner = onCleanup(@() fclose(fid)); %#ok<NASGU>
    line = fgetl(fid);
    while ischar(line) && isempty(strtrim(line))
        line = fgetl(fid);
    end
    if ~ischar(line)
        error('export_sic_preamble:EmptyJsonl', 'no JSON line in %s', path);
    end
    obj = jsondecode(line);
end

function p = local_first_existing(cands)
    p = '';
    for k = 1:numel(cands)
        if exist(cands{k}, 'file') == 2
            p = cands{k};
            return;
        end
    end
end

function v = local_field(s, name, default)
    if isfield(s, name) && ~isempty(s.(name))
        v = s.(name);
    else
        v = default;
    end
end

function local_rmdir(p)
    if exist(p, 'dir')
        rmdir(p, 's');
    end
end

function hex = local_sha256(x)
    hex = '';
    try
        md = java.security.MessageDigest.getInstance('SHA-256');
        x = x(:);
        inter = zeros(2 * numel(x), 1, 'single');
        inter(1:2:end) = real(x);
        inter(2:2:end) = imag(x);
        bytes = reshape(typecast(single(inter), 'int8'), 1, []);
        digest = md.digest(bytes);
        hex = lower(sprintf('%02x', typecast(digest(:), 'uint8')));
    catch
        hex = '';
    end
end
